  <div class="cert-header">
    <div>
      <h1 class="cert-title">DATABASE INTEGRITY AUDIT CERTIFICATE</h1>
      <div class="cert-subtitle">Shahdara Broadband ISP \xB7 Offline Storage Ledger Verification</div>
    </div>
    <div style="text-align: right; font-size: 11px; color: #64748b;">
      <div><strong>Audit Date:</strong> ${a.slice(0,10)}</div>
      <div><strong>Audit Ref:</strong> CERT-DIA-${a.slice(0,10).replace(/-/g,"")}</div>
    </div>
  </div>

